 "content": "from collections import deque

def transform(grid):
    """Mark inner rims of zero regions enclosed by 1s, and halo their enclosing walls."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = [[False] * w for _ in range(h)]
    holes = []
    exterior = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 or seen[r][c]:
                continue
            q = deque([(r, c)])
            seen[r][c] = True
            cells = []
            touches_edge = False
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                if y == 0 or x == 0 or y == h - 1 or x == w - 1:
                    touches_edge = True
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == 0 and not seen[ny][nx]:
                        seen[ny][nx] = True
                        q.append((ny, nx))
            if touches_edge:
                exterior.update(cells)
            else:
                holes.append(cells)
    # Only objects that enclose at least one zero region are decorated.
    active_ones = set()
    for cells in holes:
        for r, c in cells:
            for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                y, x = r + dy, c + dx
                if 0 <= y < h and 0 <= x < w and grid[y][x] == 1:
                    active_ones.add((y, x))
            # Color the interior rim, not the deeper core.
            if any(0 <= r+dy < h and 0 <= c+dx < w and grid[r+dy][c+dx] == 1
                   for dy, dx in ((1,0),(-1,0),(0,1),(0,-1))):
                out[r][c] = 3
    # Expand active boundary objects outward by one cardinal cell.
    for r, c in active_ones:
        for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
            y, x = r + dy, c + dx
            if 0 <= y < h and 0 <= x < w and (y, x) in exterior and grid[y][x] == 0:
                out[y][x] = 2
    return out

if __name__ == '__main__':
    import sys, json
    print(json.dumps(transform(json.load(sys.stdin))))

